async function downloadWorksheetDocx(){const s=app.session;const src=s?.mode==='worksheet'?s.ids.map(id=>bank.find(q=>q.id===id)).filter(Boolean):scopedBank().slice(0,app.amount==='all'?50:Math.max(1,Number(app.amount)||5));if(!src.length){notify('Chưa có câu để tạo Word.');return;}
 try{await EduPlanDocx.download({title:'PHIẾU HỌC TẬP HOA HOC - KNTT',grade:app.grade,chapter:app.chapter,lesson:app.lesson,student:app.name,className:app.className,questions:src,filename:'EduPlan_AI_7_2_Phieu_Hoc_Tap_'+app.grade+'.docx'});}catch(err){notify('Loi tao DOCX: '+err.message);}}
