/* EduPlan 7.5 – mindmaps from KNTT chapter/lesson map. Public, no hidden answer keys. */
function activeMindChapter(){return chapters().find(c=>c.name===app.chapter)||chapters()[0]||null;}
function activeMindLesson(ch){return ch?.lessons.find(l=>l.name===app.lesson)||ch?.lessons[0]||null;}
function setMindScope(val){app.mindScope=val==='lesson'?'lesson':'chapter';app.mindBranch=0;app.mindZoom=1;persist();}
function openMindChapter(grade,chapter){app.grade=Number(grade);app.chapter=chapter;app.lesson='';app.mindScope='chapter';app.mindBranch=0;app.mindZoom=1;app.tab='mindmap';persist();window.scrollTo(0,0);}
function openMindLesson(grade,chapter,lesson){app.grade=Number(grade);app.chapter=chapter;app.lesson=lesson;app.mindScope='lesson';app.mindBranch=0;app.mindZoom=1;app.tab='mindmap';persist();window.scrollTo(0,0);}
function mindCurrent(){const ch=activeMindChapter();if(!ch)return null;const lesson=activeMindLesson(ch);const scope=app.mindScope==='lesson'?'lesson':'chapter';const m=scope==='lesson'?mindmaps.lessons?.[`${app.grade}-${lesson?.no}`]:mindmaps.chapters?.[`${app.grade}-${ch.no}`];return m?{m,ch,lesson,scope}:null;}
function setMindBranch(index){app.mindBranch=Number(index);save();const p=$('mind-detail');if(p){p.innerHTML=mindDetail();}for(const x of document.querySelectorAll('[data-mind-branch]')){const selected=Number(x.getAttribute('data-mind-branch'))===app.mindBranch;x.classList.toggle('mind-active',selected);x.setAttribute('aria-pressed',String(selected));}}
function mindZoom(delta){app.mindZoom=Math.max(.55,Math.min(1.8,Math.round(((app.mindZoom||1)+delta)*100)/100));save();const svg=$('mind-svg');if(svg)svg.style.width=Math.round(1240*app.mindZoom)+'px';const pct=$('mind-zoom-pct');if(pct)pct.textContent=Math.round(app.mindZoom*100)+'%';}
function wrapMind(s,max=36,maxLines=3){const chunks=String(s||'').split(/\s+/),out=[];let row='';for(const c of chunks){if(!c)continue;if((row+' '+c).trim().length>max&&row){out.push(row);row=c;}else row=(row+' '+c).trim();}if(row)out.push(row);if(out.length>maxLines){const stop=out.slice(0,maxLines);stop[maxLines-1]=stop[maxLines-1].slice(0,max-2)+'…';return stop;}return out;}
function svgChem(s){return EduPlanChem.segments(s).map(p=>{const t=e(p.text);return p.position?`<tspan font-size="75%" baseline-shift="${p.position==='sub'?'sub':'super'}">${t}</tspan>`:`<tspan baseline-shift="baseline">${t}</tspan>`;}).join('');}
function mindTspans(s,x,y,opts={}){return wrapMind(s,opts.max||34,opts.lines||3).map((line,i)=>`<tspan x="${x}" dy="${i?opts.lineHeight||18:0}">${svgChem(line)}</tspan>`).join('');}
function buildMindSVG(data,scope,selected){const branch=data.branches||[],leftCount=Math.ceil(branch.length/2),rightCount=Math.floor(branch.length/2),rows=Math.max(leftCount,rightCount),BH=146,GAP=21,HEIGHT=Math.max(620,rows*(BH+GAP)+100),Y0=(HEIGHT-rows*(BH+GAP))/2+16,centerY=HEIGHT/2,colors=['#0d998d','#287ebf','#ec9131','#8865cb','#c65381','#4487aa','#4a995a','#d2842c','#6b70aa'];let body='';
const centralTitle=scope==='chapter'?`CHƯƠNG ${data.chapterNo}`:`BÀI ${data.lessonNo}`;
body+=`<rect x="548" y="${centerY-81}" width="204" height="162" rx="29" fill="#064b73" stroke="#7bcee3" stroke-width="5"/><text x="650" y="${centerY-47}" fill="#a7f5ee" text-anchor="middle" font-size="14" font-weight="800">${e(centralTitle)}</text><text x="650" y="${centerY-19}" text-anchor="middle" fill="#fff" font-size="16" font-weight="700">${mindTspans(data.title,650,centerY-19,{max:19,lines:4,lineHeight:21})}</text>`;
branch.forEach((b,i)=>{const side=i%2===0?'left':'right',idx=Math.floor(i/2),x=side==='left'?24:806,y=Y0+idx*(BH+GAP),W=472,centerNode=y+BH/2,color=colors[i%colors.length],pStartX=side==='left'?548:752,pEndX=side==='left'?x+W:x,selectedBranch=i===selected;
body+=`<path d="M${pStartX} ${centerY} C ${side==='left'?520:782} ${centerY} ${side==='left'?522:780} ${centerNode} ${pEndX} ${centerNode}" fill="none" stroke="${color}" stroke-width="${selectedBranch?6:3.5}" opacity="${selectedBranch?1:.6}"/>`;
body+=`<g class="mind-node ${selectedBranch?'mind-active':''}" data-mind-branch="${i}" tabindex="0" role="button" aria-label="${e(b.label)}" aria-pressed="${selectedBranch}" onclick="setMindBranch(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();setMindBranch(${i})}"><rect x="${x}" y="${y}" width="${W}" height="${BH}" rx="19" fill="${selectedBranch?'#eafaff':'#ffffff'}" stroke="${color}" stroke-width="${selectedBranch?4:2}"/><rect x="${x+1}" y="${y+1}" width="10" height="${BH-2}" rx="4" fill="${color}"/><text x="${x+25}" y="${y+29}" font-size="17" fill="#064c70" font-weight="800">${mindTspans(b.label,x+25,y+29,{max:44,lines:2,lineHeight:19})}</text>${(b.notes||[]).slice(0,2).map((n,j)=>`<text x="${x+25}" y="${y+80+j*24}" font-size="12.5" fill="#496b7c">${mindTspans('• '+n,x+25,y+80+j*24,{max:65,lines:1})}</text>`).join('')}</g>`;
});
return `<svg id="mind-svg" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1300 ${HEIGHT}" width="1240" height="${HEIGHT}" role="img" aria-label="Sơ đồ tư duy ${e(data.title)}"><rect width="1300" height="${HEIGHT}" rx="20" fill="#f2f9fe"/>${body}<text x="650" y="${HEIGHT-15}" text-anchor="middle" font-size="13" fill="#557c91">EduPlan AI 7.8 · Hóa ${data.grade} · SGK KNTT · Lê Bá Nhẫn – THPT Hòn Đất</text></svg>`;}
function mindDetail(){const ctx=mindCurrent();if(!ctx)return '';const {m,ch,scope}=ctx,b=m.branches[app.mindBranch]||m.branches[0];if(!b)return '';const linked=scope==='chapter'&&b.lessonNo?ch.lessons.find(l=>l.no===b.lessonNo):null;return `<div class="mind-detail-head"><span class="tag">Nhánh ${app.mindBranch+1}/${m.branches.length}</span><h3>${e(b.label)}</h3></div><ul class="mind-detail-list">${(b.notes||[]).map(x=>`<li>${chem(x)}</li>`).join('')}</ul><div class="actions">${linked?`<button class="btn primary" onclick="openMindLesson(${app.grade},${jsAttr(ch.name)},${jsAttr(linked.name)})">Xem sơ đồ Bài ${linked.no}</button><button class="btn" onclick="setLessonLink(${app.grade},${jsAttr(ch.name)},${jsAttr(linked.name)},'practice')">Luyện bài này</button>`:`<button class="btn primary" onclick="setLessonLink(${app.grade},${jsAttr(ch.name)},${jsAttr(ctx.lesson.name)},'practice')">Luyện bài đang học</button><button class="btn" onclick="setLessonLink(${app.grade},${jsAttr(ch.name)},${jsAttr(ctx.lesson.name)},'mistakes')">Ôn lỗi sai liên quan</button>`}</div>`;}
function mindMapPage(){const ctx=mindCurrent();if(!ctx)return hero('SƠ ĐỒ TƯ DUY KNTT','Chưa có sơ đồ','Vui lòng chọn khối, chương và bài.');const {m,ch,lesson,scope}=ctx,available=bank.filter(q=>q.grade===Number(app.grade)&&q.chapter===ch.name&&(scope==='chapter'||q.lesson===lesson.name)).length,linkedErrors=errorTopics.filter(t=>t.links.some(l=>l.grade===Number(app.grade)&&l.chapter===ch.name&&(scope==='chapter'||l.lesson===lesson.name))).length;
const pick=app.mindBranch>=m.branches.length?0:app.mindBranch;if(pick!==app.mindBranch)app.mindBranch=pick;
return hero('HỌC TRỰC QUAN · SƠ ĐỒ TƯ DUY HÓA HỌC','21 chương – 78 bài Kết nối tri thức','Khám phá sơ đồ theo chương hoặc theo bài; chọn từng nhánh để xem ý chính, sau đó làm câu hỏi liên quan ngay trên WebApp.')+
`<div class="grid"><section class="card"><h2>Chọn sơ đồ theo SGK KNTT</h2><div class="fields">${field('Khối lớp','grade',[[10,'Hóa 10'],[11,'Hóa 11'],[12,'Hóa 12']],app.grade)}${field('Chương','chapter',chapters().map(c=>[c.name,`Chương ${c.no}. ${c.name}`]),ch.name)}<label class="field">Cấp sơ đồ<select id="mind-scope" onchange="setMindScope(this.value)">${option('chapter','Sơ đồ toàn chương',app.mindScope)}${option('lesson','Sơ đồ từng bài',app.mindScope)}</select></label>${field('Bài học','lesson',ch.lessons.map(l=>[l.name,`Bài ${l.no}. ${l.name}`]),lesson.name)}</div><div class="actions"><button class="btn" onclick="setMindScope('chapter')">Sơ đồ chương</button><button class="btn" onclick="setMindScope('lesson')">Sơ đồ bài</button></div></section><section class="card"><h2>Học theo sơ đồ</h2><div class="stat-row"><span>Sơ đồ chương có sẵn</span><b>21</b></div><div class="stat-row"><span>Sơ đồ bài có sẵn</span><b>78</b></div><div class="stat-row"><span>Số nhánh sơ đồ đang xem</span><b>${m.branches.length}</b></div><div class="stat-row"><span>Câu hỏi liên quan trong ngân hàng</span><b>${niceNum(available)}</b></div><div class="stat-row"><span>Chuyên đề lỗi sai liên quan</span><b>${linkedErrors}</b></div><p class="help">Nhấn vào nhánh để xem giải thích và chuyển nhanh sang tự luyện đúng phạm vi.</p></section></div>`+
`<section class="card mind-paper"><div class="mind-head"><div><h2>${scope==='chapter'?'SƠ ĐỒ CHƯƠNG '+ch.no:'SƠ ĐỒ BÀI '+lesson.no}: ${e(m.title)}</h2><p class="help">${scope==='chapter'?`Hóa ${app.grade} · ${ch.lessons.length} bài học`:`Hóa ${app.grade} · Chương ${ch.no}. ${e(ch.name)}`}</p></div><div class="actions mind-controls"><button class="btn" onclick="mindZoom(-.15)" aria-label="Thu nhỏ sơ đồ">−</button><span class="tag" id="mind-zoom-pct">${Math.round((app.mindZoom||1)*100)}%</span><button class="btn" onclick="mindZoom(.15)" aria-label="Phóng to sơ đồ">+</button><button class="btn" onclick="mindZoomReset()">100%</button></div></div><div id="mind-scroll" class="mind-scroll"><div class="mind-surface">${buildMindSVG(m,scope,app.mindBranch)}</div></div><p class="help">Nếu dùng điện thoại, hãy kéo ngang trong khung sơ đồ hoặc thu nhỏ bằng nút −. Chạm từng nhánh để xem nội dung.</p><div id="mind-detail" class="mind-detail">${mindDetail()}</div><div class="actions"><button class="btn primary" onclick="downloadMindWord()">Tải sơ đồ Word .docx</button><button class="btn" onclick="downloadMindPng()">Tải ảnh PNG</button><button class="btn" onclick="downloadMindSvg()">Tải sơ đồ SVG</button><button class="btn" onclick="setLessonLink(${app.grade},${jsAttr(ch.name)},${jsAttr(scope==='chapter'?'':lesson.name)},'practice')">Luyện 5/10/15 câu</button><button class="btn" onclick="setLessonLink(${app.grade},${jsAttr(ch.name)},${jsAttr(scope==='chapter'?'':lesson.name)},'mistakes')">Ôn lỗi sai</button></div></section>`+
`<section class="card"><h2>Liên kết kiến thức và bài luyện</h2><div class="cards3">${ch.lessons.map(l=>`<button class="tool-tile" onclick="openMindLesson(${app.grade},${jsAttr(ch.name)},${jsAttr(l.name)})"><strong>Bài ${l.no}. ${e(l.name)}</strong><span>${niceNum(bank.filter(q=>q.grade===Number(app.grade)&&q.chapter===ch.name&&q.lesson===l.name).length)} câu · Xem sơ đồ bài</span></button>`).join('')}</div></section><div class="notice alert">Sơ đồ là bản tóm tắt và diễn giải kiến thức theo mục lục KNTT; không thay thế sách giáo khoa. Thực hiện thí nghiệm cần tuân thủ hướng dẫn an toàn, đối chiếu điều kiện phản ứng và đơn vị.</div>`;}
function mindZoomReset(){app.mindZoom=1;save();const svg=$('mind-svg');if(svg)svg.style.width='1240px';const pct=$('mind-zoom-pct');if(pct)pct.textContent='100%';}
function mindSvgText(){const svg=$('mind-svg');if(!svg)throw Error('Chưa tải xong sơ đồ SVG.');const clone=svg.cloneNode(true);clone.removeAttribute('style');clone.setAttribute('width','1300');clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('xmlns:xlink','http://www.w3.org/1999/xlink');return new XMLSerializer().serializeToString(clone);}
function downloadMindBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function mindFileName(ext){const ctx=mindCurrent();return `EduPlan_AI_7_6_So_Do_${ctx.scope==='chapter'?'Chuong_'+ctx.ch.no:'Bai_'+ctx.lesson.no}_Hoa_${app.grade}.${ext}`;}
function downloadMindSvg(){try{downloadMindBlob(new Blob([mindSvgText()],{type:'image/svg+xml;charset=utf-8'}),mindFileName('svg'));}catch(err){notify('Không tải được SVG: '+err.message);}}
async function mindToPngData(){const ctx=mindCurrent();if(!ctx)throw Error('Chưa chọn sơ đồ.');const xml=mindSvgText();const svg=$('mind-svg'),view=svg.viewBox.baseVal;const W=Math.round(view.width),H=Math.round(view.height),img=new Image();return new Promise((resolve,reject)=>{const url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml;charset=utf-8'}));img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=W*2;canvas.height=H*2;const c=canvas.getContext('2d');c.fillStyle='#ffffff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/png'));}catch(err){URL.revokeObjectURL(url);reject(err);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Không dựng được ảnh sơ đồ.'));};img.src=url;});}
async function downloadMindPng(){try{const data=await mindToPngData();const byte=Uint8Array.from(atob(data.split(',')[1]),c=>c.charCodeAt(0));downloadMindBlob(new Blob([byte],{type:'image/png'}),mindFileName('png'));}catch(err){notify('Không xuất được PNG: '+err.message);}}
async function downloadMindWord(){const ctx=mindCurrent();if(!ctx)return;try{const png=await mindToPngData();await EduPlanDocx.downloadMindMap({title:ctx.m.title,grade:app.grade,chapter:ctx.ch.name,lesson:ctx.scope==='lesson'?ctx.lesson.name:'Toàn chương',scope:ctx.scope,branches:ctx.m.branches,pngData:png,filename:mindFileName('docx')});}catch(err){console.error(err);notify('Chưa thể xuất DOCX sơ đồ: '+err.message);}}

