function checkQaEquation(){const x=$('qa-equation'),out=$('qa-equation-result');if(!x||!out)return;const r=EduPlanChem.checkEquation(x.value);out.className='notice '+(r.status==='balanced'?'success':'alert');out.textContent=({balanced:'Đã cân bằng số nguyên tử. ',unbalanced:'Chưa cân bằng. ',unsupported:'Chưa kiểm tra được. ',invalid:'Sai cấu trúc. '})[r.status]+r.detail;}


