/* A real test may only draw questions eligible for server-side grading. */
const oldStart77=startQuiz;
startQuiz=function(mode='practice',reviewOnly=false){
 const m=typeof mode==='boolean'?(mode?'selftest':'practice'):mode;
 if(m!=='selftest')return oldStart77(mode,reviewOnly);
 const scope=scopedBank().filter(q=>gradeCatalogSet.has(q.id));
 if(!scope.length){notify('\u0110ang kh\u00f4ng c\u00f3 c\u00e2u c\u00f3 kh\u00f3a r\u00e0 so\u00e1t trong ph\u1ea1m vi. H\u00e3y ch\u1ecdn ch\u01b0\u01a1ng kh\u00e1c ho\u1eb7c chuy\u1ec3n sang Luy\u1ec7n t\u1eadp.');return;}
 const marked=new Set(recent().flatMap(s=>s.flagged||[])),pool=reviewOnly?scope.filter(q=>marked.has(q.id)):scope;
 if(!pool.length){notify('Kh\u00f4ng c\u00f3 c\u00e2u c\u1ea7n \u00f4n l\u1ea1i ph\u00f9 h\u1ee3p.');return;}
 const n=app.amount==='all'?Math.min(pool.length,50):Math.max(1,Math.min(50,Number(app.amount)||5));
 const seen=new Set(recent().flatMap(s=>(s.answers||[]).map(a=>a.id)));
 const chosen=seededShuffle(pool).sort((a,b)=>Number(seen.has(a.id))-Number(seen.has(b.id))).slice(0,n);
 app.session={id:'s-'+Date.now(),mode:'selftest',scope:{grade:app.grade,chapter:app.chapter,lesson:app.lesson,kind:app.kind,difficulty:app.difficulty},ids:chosen.map(q=>q.id),index:0,started:Date.now(),finished:false,flagged:[],answers:[],draft:{},selfReview:{}};
 app.tab='selftest';persist();
 if(chosen.length<n)notify('Ch\u1ec9 c\u00f3 '+chosen.length+'/'+n+' c\u00e2u \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n ch\u1ea5m trong ph\u1ea1m vi n\u00e0y.');
};

